tests_run.command:
python3 -B -c 'import ast, hashlib, json; from pathlib import Path; paths = [Path("spikes/runtime/probe.py"), Path("spikes/runtime/test_cleanup.py"), Path("spikes/runtime/README.md")]; results = [];
for path in paths:
 source = path.read_text(); assert not any(line.rstrip() != line for line in source.splitlines()), str(path);
 if path.suffix == ".py": compile(ast.parse(source, filename=str(path)), str(path), "exec");
 results.append({"path": str(path), "sha256": hashlib.sha256(path.read_bytes()).hexdigest(), "lines": len(source.splitlines())});
print(json.dumps({"syntax_and_whitespace": "passed", "files": results}, indent=2))'
